local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[10296] = {id=10296,name="The Black Morass",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=2366,description="The Infinite Dragonflight have abandoned all pretense of subtlety. They plot to destroy the Guardian, Medivh, and prevent the Dark Portal from ever opening. While outwardly, this may appear a boon to the forces of the Alliance, it is in actuality catastrophic and will result in your world ending. You must venture through the timeway leading to the Black Morass . Go west and then south, past my future self, until you reach the tunnel that houses the swamp specimens. Cross over and speak with Sa'at .",ends={{npcID=20201,zoneID=2366}},questType="dungeon"},
[12431] = {id=12431,name="The Conquest Pit: Final Showdown",level=15,requiredLevel=15,faction="horde",expansion=8,zoneID=394,mapID=116,description="You must've really upset Krenna. She and Gorgonna have had a spat and you're wanted in the pit immediately. There are some wild rumors that it's a fight to the death! That would be bad news for you, but great news for our business venture! At any rate, you can't run away from fate... best get in there on the quick and get it over with.",starts={{npcID=27719,x=0.224,y=0.638,mapID=116}},ends={{npcID=27102,x=0.208,y=0.64,mapID=116}},coords={x=0.224,y=0.638,source="quest_giver",mapID=116},questType="group"},
[12807] = {id=12807,name="The Story Thus Far...",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=210,mapID=118,description="We have much to do, but first I believe a short refresher is in order. We death knights have a colorful past with our Scarlet friends who idiotically rest comfortably in the harbor below us to the northwest. When you are ready for an earful, speak with me again and I shall provide enlightenment.",starts={{npcID=29344,x=0.196,y=0.48,mapID=118}},ends={{npcID=29344,x=0.196,y=0.48,mapID=118}},coords={x=0.196,y=0.48,source="quest_giver",mapID=118},questType="standard"},
[13161] = {id=13161,name="The Rider of the Unholy",level=25,requiredLevel=25,faction="both",expansion=8,zoneID=210,mapID=118,description="It's time that we start cutting off the heads of the beast. I served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless. Rokir 's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious. Be nimble, , and do not take him lightly.",starts={{npcID=30944,x=0.54,y=0.71,mapID=118}},ends={{npcID=30944,x=0.54,y=0.71,mapID=118}},coords={x=0.54,y=0.71,source="quest_giver",mapID=118},questType="group"},
[13175] = {id=13175,name="Regaining Control",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[13176] = {id=13176,name="Preparing the Delivery",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[13184] = {id=13184,name="Outliving Usefulness",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=210,mapID=118,questType="standard"},
[24928] = {id=24928,name="To The Ground!",level=15,requiredLevel=15,faction="horde",expansion=8,zoneID=440,mapID=71,description="I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate. Luckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there. Try not to stand downwind.",starts={{npcID=38703,x=0.718,y=0.454,mapID=71}},ends={{npcID=38703,x=0.718,y=0.454,mapID=71}},coords={x=0.718,y=0.454,source="quest_giver",mapID=71},questType="standard"},
[25053] = {id=25053,name="To The Ground!",level=15,requiredLevel=15,faction="alliance",expansion=8,zoneID=440,mapID=71,description="You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing. I mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!",starts={{npcID=38704,x=0.722,y=0.452,mapID=71}},ends={{npcID=38704,x=0.722,y=0.452,mapID=71}},coords={x=0.722,y=0.452,source="quest_giver",mapID=71},questType="standard"},
[27141] = {id=27141,name="Exploding Through",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="What a find! Right here... exactly where my notes predicted it would be. With any luck, inside this chamber will lie clues to the location of the legendary Coffer of the Promise. That's right, . It's not just a myth. I believe it truly exists. I'll explain more later. For now, just give me a hand with these explosives.",starts={{npcID=44860,x=0.644,y=0.224,mapID=249}},ends={{npcID=45180,x=0.646,y=0.286,mapID=249}},coords={x=0.644,y=0.224,source="quest_giver",mapID=249},questType="standard"},
[27760] = {id=27760,name="Artificial Intelligence",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="Emergency code: 55-729. Upper cerebral cortex functions in expedition members have been compromised. Please report to your nearest terminal location, to the southeast of the Sunstone Terrace, for further analysis.",ends={{npcID=206293,x=0.741,y=0.644,mapID=249}},questType="standard"},
[27779] = {id=27779,name="Gnomebliteration",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="I have downloaded my program to the fusion core and have complete control over it. I've created a small pocket of air inside to avoid vaporizing user . I will yield control of all movement functions so I can dedicate my cycles to keeping the core stable. Go down the hill and neutralize as many of the expedition members as possible. My analysis reveals you might feel... \"guilt\" as a result of such high fatality numbers. User , you must be assured that expedition members are without hope.",starts={{npcID=46750,x=0.772,y=0.632,mapID=249}},ends={{npcID=46750,x=0.772,y=0.632,mapID=249}},coords={x=0.772,y=0.632,source="quest_giver",mapID=249},questType="standard"},
[27961] = {id=27961,name="Out of Place",level=15,requiredLevel=15,faction="both",expansion=8,zoneID=51,mapID=32,description="The gorge is an unforgiving place. We don't get a whole lot of fuzzy wildlife wandering around here. We tried bringing in some wild game, but they haven't fared well at all. There's just no food for them to eat. Now the nearby spiders - which were already dangerous - are getting big and fat on chicken meat. We'll never get rid of all the spiders, but we can salvage what few chickens remain. Not only will you be feeding the Brotherhood, you'll be saving them a painful death by spider bite.",starts={{npcID=47267,x=0.684,y=0.534,mapID=32}},ends={{npcID=47267,x=0.684,y=0.534,mapID=32}},coords={x=0.684,y=0.534,source="quest_giver",mapID=32},questType="standard"},
[28028] = {id=28028,name="Siege!",level=15,requiredLevel=15,faction="both",expansion=8,zoneID=51,mapID=32,description="That Overseer Oilfist couldn't'a picked a worse time to ask me to join a fight. My summit's already under siege! It's nothin' my guards can't handle, but still, it won't be easy for me to just pick up and send some dwarves into that infernal gorge. Tell ya what: you take out their marksmen that're holding our fortress under siege, and I'll consider your offer. Ye'll find 'em slinkin' around the flats to the east.",starts={{npcID=47393,x=0.408,y=0.518,mapID=32}},ends={{npcID=47393,x=0.408,y=0.518,mapID=32}},coords={x=0.408,y=0.518,source="quest_giver",mapID=32},questType="standard"},
[28404] = {id=28404,name="I'll Do It By Hand",level=30,requiredLevel=30,faction="both",expansion=8,zoneID=5034,mapID=249,description="Yes, this all looks familiar enough. Thanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction. As soon as I get started, you can count on that titan construct to try and stop me. That's where you come in. I don't need to remind you of what's riding on this. Take down that guardian!",starts={{npcID=48558,x=0.39,y=0.232,mapID=249}},ends={{npcID=48558,x=0.39,y=0.232,mapID=249}},coords={x=0.39,y=0.232,source="quest_giver",mapID=249},questType="standard"},
