[56267] = {id=56267,name="Whispers of N'Zoth",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=9667,mapID=84,description="Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.",starts={{npcID=154465,x=0.51,y=0.888,mapID=1165},{npcID=155496,x=0.852,y=0.322,mapID=84},{npcID=155496,x=0.466,y=0.646,mapID=84}},ends={{npcID=152365,x=0.524,y=0.69,mapID=84}},coords={x=0.51,y=0.888,source="quest_giver",mapID=84},questType="standard"},
