[57053] = {id=57053,name="Blunt Force Testing",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=11455,mapID=1532,description="Now that we have the thermoplugs we're ready for our next test of the prototype X-52 Personnel Armor ! Unfortunately, my lab assistants have either quit or expired. What a pity! But their loss is your gain, ... now YOU get to wear the X-52 Personnel Armor ! How exciting! The next test will be conducted by my new mechanized lab assistant . Head over to the main workshop and press the big red button to begin. Don't worry, I'll be giving you directions over the X-52's built in intercom!",starts={{npcID=156520,x=0.52,y=0.594,mapID=1532}},ends={{npcID=156520,x=0.52,y=0.594,mapID=1532}},coords={x=0.52,y=0.594,source="quest_giver",mapID=1532},questType="standard"},
[57099] = {id=57099,name="A Dreadful Roundup",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Welcome to The Banewood, Maw Walker. As Huntmaster it is my duty to lead the Fearstalk. Our first order of business is to collect the souls selected for the hunt. In the woods behind me we have souls who have been ripening for several hundred years now. Go choose the souls who will be hunted today.",questType="standard"},
[57100] = {id=57100,name="Feeding Time is Over",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="A crucial element to a successful Fearstalk is our tool: the fangs of a terrorbeast. Their fangs are perfect for revealing the scent of their prey once bound to a soul. There's plenty of them in the forest surrounding the ripening souls. Go and collect some from their corpses. Their population is a bit large right now anyhow.",questType="standard"},
[57112] = {id=57112,name="Test Shared Quest",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[57155] = {id=57155,name="Blinding the Eye",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=10266,description="Ah yes, just the I wanted to see. I can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection. Through my research I have learned a less painful way of removing the infection. Speak with me, and let's put an end to this nightmare.",questType="standard"},
[57156] = {id=57156,name="Blinding the Eye",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=10266,description="You finally arrived . Dat dark mojo on you has lingered for too long. N'Zoth be defeated and we need to cleanse all de traces of his infection from you. Dis won't hurt. Much. Tell me when you are ready to begin.",questType="standard"},
[57185] = {id=57185,name="Dutybound",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Welcome to the fight, . You're with us now. Take a moment and introduce yourself. I will meet you by Draven at the lodge.",questType="standard"},
[57225] = {id=57225,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[57226] = {id=57226,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[57228] = {id=57228,name="The Assault on Dredhollow",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="The time is upon us, Maw Walker. The Fearstalker's hunters are descending upon us. We have done all we can do to prepare for their assault. Here. I fashioned this out of the supplies you brought me. Use it to destroy the Fearstalker's forces . The fight begins.",questType="standard"},
[57240] = {id=57240,name="Where is Prince Renathal?",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="This is not victory, $p. If Prince Renathal does not return, we've merely delayed defeat. The Prince was last seen during an assault on the Master's keep alongside Duke Theotar. We don't know the Prince's fate, but we've learned that Duke Theotar was banished to the Ember Ward. The Ember Ward is a land of madness and torture. Blighted by the Light, the Master sends his most hated enemies there to suffer unending agony. Enter the Ember Ward, find Theotar, and discover the Prince's fate.",starts={{npcID=168217,x=0.432,y=0.738,mapID=1525}},ends={{npcID=157199,x=0.39,y=0.66,mapID=1525}},coords={x=0.432,y=0.738,source="quest_giver",mapID=1525},questType="standard"},
[57370] = {id=57370,name="Assault: The Black Empire",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=5034,mapID=249,questType="standard"},
[57371] = {id=57371,name="Assault: Aqir Unearthed",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=5034,mapID=249,questType="standard"},
[57372] = {id=57372,name="The Drag",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=15946,questType="standard"},
[57377] = {id=57377,name="A Hand Offered",level=50,requiredLevel=50,faction="horde",expansion=8,zoneID=8044,questType="standard"},
[57380] = {id=57380,name="Sign Your Own Death Warrant",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Ember Ward only for bad buds! Stonehead squints at you and shakes head.> You not look like other bad buds! Bad buds come with bad paper!",starts={{npcID=157199,x=0.39,y=0.66,mapID=1525}},ends={{npcID=157199,x=0.39,y=0.66,mapID=1525}},coords={x=0.39,y=0.66,source="quest_giver",mapID=1525},questType="standard"},
[57401] = {id=57401,name="Reconstructing \"The Final Truth\"",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=9667,mapID=84,description="Long have I studied the secrets of the Old Gods. I have traversed the whole of Azeroth in search of esoteric texts, lost archives, and forbidden knowledge, all in the name of preparing for the horror to come. No amount of research could have prepared me for the depths of the insanity I would find within this book. A madness so absolute that only the Shath'yar language can convey it. Find me the final pages of this accursed tome, . I wish to learn what I need from it and be done with it forever.",starts={{npcID=155496,x=0.852,y=0.322,mapID=84},{npcID=155496,x=0.466,y=0.646,mapID=84}},ends={{npcID=155496,x=0.852,y=0.322,mapID=84},{npcID=155496,x=0.466,y=0.646,mapID=84}},coords={x=0.852,y=0.322,source="quest_giver",mapID=84},questType="standard"},
[57405] = {id=57405,name="Chasing Madness",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="An adversary with no ferry cannot be merry unless it is wary!",starts={{npcID=157588,x=0.37,y=0.632,mapID=1525}},ends={{npcID=157639,x=0.38,y=0.606,mapID=1525}},coords={x=0.37,y=0.632,source="quest_giver",mapID=1525},questType="standard"},
[57426] = {id=57426,name="My Terrible Morning",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="You simply won't believe what happened to me! I was out for my daily stroll when Marquis Pummeler and his band of ruffians assailed me! Amongst the many unfortunate and ungentlemanly behaviors they displayed was destroying my parasol. A tragedy of the highest order! Without it, I'm afraid I'm left quite vulnerable to the oppressive Light that curses this land. The Marquis controls a coveted shaded hideout nearby. Will you avenge my parasol and teach this ruffian some manners?",starts={{npcID=157639,x=0.38,y=0.606,mapID=1525}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57427] = {id=57427,name="Unbearable Light",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Have you encountered an ash ghoul yet? Wretches crawling on the ground. Jump on everything. Terrible table manners. That is the unfortunate fate awaiting all venthyr exposed to the Light for too long. The overwhelming pain it causes us breaks our willpower, our mind, and finally our body. With the right skills, it is possible to reverse the Light's desecration if it is treated quickly. But the ash ghouls in this Light-burned crater are beyond redemption. There is only one mercy left.",starts={{npcID=157639,x=0.38,y=0.606,mapID=1525}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57428] = {id=57428,name="Theotar's Mission",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh the Accuser sent you? How keen! I do, in fact, know the fate of Prince Renathal... at least part of it. When our assault on the Master's keep failed, we were both captured. I was banished to the Ember Ward, but the Prince was dragged off to Sinfall. I'm cultivating an escape from this Light-blighted land to follow after him, but the Light here... it makes it hard to think. My parasol once protected me, but the ruffians destroyed it. Help me rebuild it, and we'll find the Prince together.",starts={{npcID=157639,x=0.38,y=0.606,mapID=1525}},coords={x=0.38,y=0.606,source="quest_giver",mapID=1525},questType="standard"},
[57442] = {id=57442,name="Lost in the Desiccation",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Theotar incapable of forming coherent sentences. Instead of telling you how to get to his hideout, he mumbles incoherently while pointing in random directions.> Lost... Syb... Tubbins ... Late for tea... Theotar 's hideout a different way.>",ends={{npcID=157801,x=0.31,y=0.576,mapID=1525}},questType="standard"},
[57457] = {id=57457,name="Shaking 'Shrooms",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,description="The mushrooms in there need your help, ! Some of the larger mushrooms become laden with spores. It is one of my duties to help disperse them and grow the grove, but it is too dangerous for me in there. If you're going to go in, do you mind giving any particularly full mushrooms a good shake for me? That should get most of the spores loose until we can secure the grove.",questType="standard"},
[57460] = {id=57460,name="Tubbins's Tea",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Theotar teach Tubbins special tea that make Light go away! Tubbins good tea maker! Watch Tubbins make Theotar feel good! Then Tubbins feel good!",starts={{npcID=157801,x=0.31,y=0.576,mapID=1525}},ends={{npcID=157801,x=0.31,y=0.576,mapID=1525}},coords={x=0.31,y=0.576,source="quest_giver",mapID=1525},questType="standard"},
[57461] = {id=57461,name="An Uneventful Stroll",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I hope I wasn't too unpleasant while under the Light's influence. I do try to restrain myself, but the pain it causes is... maddening. Anyway, that tea picked me right up! When I last saw Prince Renathal, the Master was dragging him off to that big tower looming over the Ember Ward. Myself and a few others have been working to gain access to that tower from below, but there are... obstacles. When you're ready to depart, I will lead you to our headquarters of sorts, the Sanctuary of the Mad.",starts={{npcID=158542,x=0.312,y=0.574,mapID=1525}},ends={{npcID=158694,x=0.32,y=0.476,mapID=1525}},coords={x=0.312,y=0.574,source="quest_giver",mapID=1525},questType="standard"},
[57506] = {id=57506,name="Light Lost",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[57510] = {id=57510,name="Darklord Taraxis",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[57513] = {id=57513,name="Enemy of My Enemy",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="I have no doubt you have questions. Know that we share enemies in this land. For now, we must move. I will get you to a safer location and then we can speak.",questType="standard"},
[57537] = {id=57537,name="Covering our Tracks",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="I belong to the House of the Chosen. We have a stronghold to the south, it should be safe there. We'll fly the rest of the way. Approach my flayedwing when you are prepared.",questType="standard"},
[57641] = {id=57641,name="Master Ryson's All Seeing Eye",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=10458,mapID=25,description="Your war in the heart of Alterac means nothing to the Syndicate, . We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you.",starts={{npcID=13151,mapID=25}},ends={{npcID=13151,mapID=25}},questType="pvp"},
[57642] = {id=57642,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[57643] = {id=57643,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,starts={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},ends={{npcID=180746,x=0.334,y=0.659,mapID=87},{npcID=180746,x=0.491,y=0.782,mapID=85}},coords={x=0.334,y=0.659,source="quest_giver",mapID=85},questType="standard"},
[57658] = {id=57658,name="The Final Leg",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11510,mapID=1565,description="Please, I must get to Glitterfall Basin. I thought I was being careful. I did not realize I was being hunted until it was too late. Such is the nature of the forest. I am too close to fall here. The Lady herself invited me to come join her. She said I would be safe. Can you take me to her?",questType="standard"},
[57677] = {id=57677,name="A Soulbind In Need",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Pelagos is my Soulbind. He is my brother, my closest friend, my mentor, and my student. He knows me completely, and I him. It is a bond stronger than any other. That he now struggles is a torment to me, but I am forbidden from intervening. An aspirant must succeed or fail on their own merits, or the trial is forfeit. I am bound by this law... but you are not. Please bring Pelagos back to me. This will not be his last trial. Not when he may finally have a chance.",starts={{npcID=165107,x=0.482,y=0.726,mapID=1533}},ends={{npcID=165112,x=0.482,y=0.724,mapID=1533}},coords={x=0.482,y=0.726,source="quest_giver",mapID=1533},questType="standard"},
[57724] = {id=57724,name="Securing Sinfall",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="They're all still active... The stoneborn, the gargon, the stone fiends... All of 'em! Don't got much time. They're always watching. Breakfist points up.> Vulca told me to follow that big beam of Light in the sky. Goes to a tower guarded by a big old brute, though. Couldn't get in.",starts={{npcID=169105,x=0.304,y=0.456,mapID=1525}},ends={{npcID=158716,x=0.298,y=0.422,mapID=1525}},coords={x=0.304,y=0.456,source="quest_giver",mapID=1525},questType="standard"},
[57766] = {id=57766,name="War with the Horde",level=10,requiredLevel=10,faction="alliance",expansion=8,zoneID=1637,mapID=85,description="Good to see you've received proper training as a . We'll need it for what's next. The Alliance's war with the Horde has reached a fevered pitch... and we've lost a lot of good soldiers. King Anduin is looking for aid in an operation to bolster our forces. I told him you'd be a good fit for the job. Before you meet him, let me get get you caught up on what has been happening so far.",questType="standard"},
[57850] = {id=57850,name="Storied Partnerships",level=1,requiredLevel=1,faction="none",expansion=8,questType="standard"},
[57852] = {id=57852,name="Dungeon Adventure",level=1,requiredLevel=1,faction="none",expansion=8,questType="standard"},
[57853] = {id=57853,name="Battleforged Team",level=1,requiredLevel=1,faction="none",expansion=8,questType="standard"},
[57872] = {id=57872,name="Bring More Friends!",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11510,mapID=1565,description="This is only the beginning, friend. I must thank you again for rescuing me. Now that we have found a safe route, I am but the first of many. Druids from all around Ardenweald have heard of the safety of this glade, and I wish to bring them all here. I have known Roriel for most of my time in this place. She is a capable healer, despite her appearance. She would be a fine addition to this place. She was last seen near Tirna Fein to the west. Please let her know the way is clear.",questType="standard"},
[57961] = {id=57961,name="Heroic: Battle for Darkshore",level=1,requiredLevel=1,faction="horde",expansion=8,questType="standard"},
[57962] = {id=57962,name="Heroic: Battle for Darkshore",level=1,requiredLevel=1,faction="alliance",expansion=8,questType="standard"},
[57966] = {id=57966,name="You Go First",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="You've proven useful. So, I am going to require you to disarm the defenses of this hall. Please take care not to die too quickly. I'd like to have the spear before the end of this eon.",starts={{npcID=159272,x=0.432,y=0.384,mapID=1533}},ends={{npcID=159272,x=0.432,y=0.384,mapID=1533}},coords={x=0.432,y=0.384,source="quest_giver",mapID=1533},questType="standard"},
[57973] = {id=57973,name="Heroic: Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",expansion=8,questType="standard"},
[57974] = {id=57974,name="Heroic: Battle for Darkshore",level=50,requiredLevel=50,faction="horde",expansion=8,questType="standard"},
[58160] = {id=58160,name="For Queen and Grove!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="A stunning performance... in more ways than one. So much has transpired on Azeroth in my absence. But there was one dream I did not see portrayed onstage. I dreamt of Tyrande, engulfed in darkness, twisted by anger and a thirst for vengeance. I witnessed a forbidden ritual, the rise of a new Night Warrior, and a hunt that can end only in tragedy. That too must be real. Ysera shakes her head.> The Winter Queen awaits you in the Heart of the Forest. We had best be on our way.",starts={{npcID=160500,x=0.424,y=0.452,mapID=1565}},ends={{npcID=156634,x=0.454,y=0.656,mapID=1565},{npcID=156634,x=0.506,y=0.314,mapID=1565}},coords={x=0.424,y=0.452,source="quest_giver",mapID=1565},questType="standard"},
[58273] = {id=58273,name="Servant of N'Zoth",level=0,requiredLevel=0,faction="horde",expansion=8,questType="standard"},
[58274] = {id=58274,name="Servant of N'Zoth",level=0,requiredLevel=0,faction="alliance",expansion=8,questType="standard"},
[58297] = {id=58297,name="Faceless Mask of the Daredevil",level=50,requiredLevel=50,faction="both",expansion=8,description="The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.",questType="standard"},
[58314] = {id=58314,name="Faceless Mask of the Burned Bridge",level=50,requiredLevel=50,faction="both",expansion=8,description="The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.",questType="standard"},
[58316] = {id=58316,name="Faceless Mask of the Dark Imagination",level=50,requiredLevel=50,faction="both",expansion=8,description="These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.",questType="standard"},
[58317] = {id=58317,name="Faceless Mask of the Pained",level=50,requiredLevel=50,faction="both",expansion=8,description="Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.",questType="standard"},
[58318] = {id=58318,name="Faceless Mask of the Long Night",level=50,requiredLevel=50,faction="both",expansion=8,description="The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.",questType="standard"},
[58328] = {id=58328,name="TBD",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="Bribe Boulderfoot",questType="standard"},
[58596] = {id=58596,name="Specter Of War: Visectus",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,questType="standard"},
[58625] = {id=58625,name="Connecting the Dots",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting. He went off to meet with some member of the House of Rituals. There were a few of his guards with him. While it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.",questType="standard"},
[58664] = {id=58664,name="Ultimate Makeover",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls. Emeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard. You will assist me in rebuilding Emeni's construct.",questType="standard"},
[58707] = {id=58707,name="Sorting Through Visions",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[58769] = {id=58769,name="REUSE ME",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,description="Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband. But I will get them back. If you are our new champion then you will help me for the good of Ardenweald . Death did not part us. I will not be torn from him now.",questType="standard"},
[58801] = {id=58801,name="Enter the Void",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,description="My faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...",starts={{npcID=341831,x=0.603,y=0.51,mapID=1527}},coords={x=0.603,y=0.51,source="quest_giver",mapID=1527},questType="standard"},
[58887] = {id=58887,name="Alpaca It In",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,starts={{npcID=162765,x=0.552,y=0.698,mapID=1527}},ends={{npcID=162765,x=0.552,y=0.698,mapID=1527}},coords={x=0.552,y=0.698,source="quest_giver",mapID=1527},questType="standard"},
[58904] = {id=58904,name="Shards of Corruption",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10833,mapID=1527,ends={{npcID=341831,x=0.603,y=0.51,mapID=1527}},questType="standard"},
[58918] = {id=58918,name="Huwerath",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[58951] = {id=58951,name="Lakeshire's Last Stand",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1533,description="There's no time to evacuate... not if the Scourge are here! Board the windows! Get everybody inside! Our only hope is to hide.",starts={{npcID=163111,x=0.288,y=0.41,mapID=49}},ends={{npcID=162542,x=0.326,y=0.398,mapID=49},{npcID=162542,x=0.32,y=0.212,mapID=1533},{npcID=162542,x=0.454,y=0.576,mapID=1533}},coords={x=0.288,y=0.41,source="quest_giver",mapID=1533},questType="standard"},
[58979] = {id=58979,name="I MADE You!",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I have had it with this insolence! I have an idea to reset this Mnemis's personality, but you will need to keep it busy. It will try to fight you, through whatever means it posseses. I suggest you try not to perish. Kleia can hold her own, so hide behind her if so inclined. Hop to it!",starts={{npcID=167034,x=0.572,y=0.552,mapID=1533}},ends={{npcID=167035,x=0.588,y=0.652,mapID=1533}},coords={x=0.572,y=0.552,source="quest_giver",mapID=1533},questType="standard"},
[59002] = {id=59002,name="A Shaman's Duty",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=10424,mapID=1409,description="Greetings, young one. Your companions cannot see me. Only you, for you have been trained in the ways of a shaman. The shadow energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from the surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.",starts={{npcID=163329,x=0.522,y=0.554,mapID=1409}},ends={{npcID=163329,x=0.522,y=0.554,mapID=1409}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59007] = {id=59007,name="Soul Well",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[59076] = {id=59076,name="The Minions of Mayhem",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10565,mapID=1670,description="To all downtrodden and unappreciated hard workers of the Shadowlands: the time has come to rise up. Rise up and stick it to the fangs and the wings and the bonemen! Stick it to the brokers and the bossmons! I says we go into business for ourselves! Come to our secret meeting at the Ledge of Destiny. To all not-downtrodden warlords, Maw Walkers, and morally flexible powerful denizens: We are currently hiring muscle. If interested, please attend. Don't tell the fuzz.",questType="standard"},
[59126] = {id=59126,name="Supply Chain",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="My friend! I could sure use your expertise right now. One of our wagon convoys was attacked nearby! It was transporting critical supplies... and new goods for me to sell! It's important--no--vital, that we recover as much of that equipment as possible. So, you ready to go? Let's head out and salvage what we can!",starts={{npcID=159238,x=0.552,y=0.682,mapID=1536}},ends={{npcID=167150,x=0.55,y=0.686,mapID=1536}},coords={x=0.552,y=0.682,source="quest_giver",mapID=2151},questType="standard"},
[59175] = {id=59175,name="The Eternal Revenge",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,questType="standard"},
[59184] = {id=59184,name="Borr-Geth",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[59225] = {id=59225,name="[DNT] Azerite Reward Test Quest - BJI",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=8499,mapID=862,description="This quest should award Azerite Armor and Azerite if you have a HoA, and armor stripped of powers and no Azerite if you do not have a heart of azeroth yet.",questType="standard"},
[59230] = {id=59230,name="Dartanos, Flayer of Souls",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[59316] = {id=59316,name="Binding Power",level=60,requiredLevel=60,faction="none",expansion=8,description="To soulbind with another is not an irrevocable bond. However, it is not to be entered into lightly. You will experience one another's pasts. Your hopes, fears, dreams, your very memories--if any still linger. You will become kindred spirits in the truest sense. Once complete, your connection will transcend physical space and make you stronger in more than mere brawn.",questType="standard"},
[59317] = {id=59317,name="Strengthening the Bond",level=60,requiredLevel=60,faction="none",expansion=8,description="Do you feel it, too? Our connection is stronger than I imagined could be possible. I have been told that the bond will continue to grow over time, though we do have the ability to accelerate the process. Sinfall needs our strength. Perhaps it is best we engage in this method now.",questType="standard"},
[59322] = {id=59322,name="Shared Souls",level=60,requiredLevel=60,faction="none",expansion=8,description="The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.",questType="standard"},
[59327] = {id=59327,name="In the Ruin of Rebellion",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10986,mapID=1525,description="Well, here we are -- Sinfall. Last I saw, the Master was dragging Prince Renathal and his most loyal followers here in a prison convoy. However, this is a forbidden place, wrapped in rumors and mystery. I heard it was once the workshop of Denathrius, where he performed dark experiments. Intriguing to be sure, but we are here to find Renathal. Search below, but proceed with caution. I will send word for the Accuser to make her way here with what allies she can muster.",starts={{npcID=158716,x=0.298,y=0.422,mapID=1525}},ends={{npcID=158615,x=0.324,y=0.396,mapID=1525}},coords={x=0.298,y=0.422,source="quest_giver",mapID=1525},questType="standard"},
[59441] = {id=59441,name="Soulsmith Yol-Mattar",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="standard"},
[59604] = {id=59604,name="Takin' Down the Beast",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,questType="standard"},
[59605] = {id=59605,name="Takin' Down the Beast",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,questType="standard"},
[59840] = {id=59840,name="Divine Gratitude",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,questType="standard"},
[59870] = {id=59870,name="[OLD NOT USED]",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13367,mapID=1662,questType="standard"},
[59882] = {id=59882,name="Sure Bet",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=11462,mapID=1536,description="You appear to have great profit potential. There are many interested parties willing to bet upon your performance in the Theater of Pain. Go now, Louison will arrange your appearance.",questType="standard"},
[59912] = {id=59912,name="[OLD NOT USED]",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13367,mapID=1662,description="Now that you have seen the basics it is time for us to expand your understanding. I hope your little mind will be able to hold this information. You seem capable so far, but you are so small. I'll be intrigued to see if you are bigger on the inside. First. You need to learn more about the catalysts. There should be a small number growing in this very grove. Fetch me some and I can explain what they are.",questType="standard"},
[59925] = {id=59925,name="[OLD NOT USED]",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,questType="standard"},
[59929] = {id=59929,name="Murloc Mania",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The shore is littered with shipwrecks. This must be where the lost expedition crashed. We'll need more supplies to help the injured recover. The nearby murlocs stole most of what washed up. Slay those murlocs to get back what belongs to the Horde.",starts={{npcID=166782,x=0.618,y=0.828,mapID=1409}},ends={{npcID=166782,x=0.618,y=0.828,mapID=1409}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59930] = {id=59930,name="Emergency First Aid",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="We must treat our wounded before we can begin for the missing expedition. Take this first aid kit and tend to the survivors. I'll handle the others nearby.",starts={{npcID=166782,x=0.618,y=0.828,mapID=1409}},ends={{npcID=166782,x=0.618,y=0.828,mapID=1409}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59931] = {id=59931,name="Finding the Lost Expedition",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Breka Grimaxe went north to look for survivors. Join her to see what she's found. I'm going to go up ahead to see if I can find anyone else. We'll meet again further within the island.",starts={{npcID=166782,x=0.618,y=0.828,mapID=1409}},ends={{npcID=166854,x=0.582,y=0.746,mapID=1409},{npcID=166906,x=0.582,y=0.746,mapID=1409}},coords={x=0.618,y=0.828,source="quest_giver",mapID=1409},questType="standard"},
[59932] = {id=59932,name="Cooking Meat",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This is Won'sa , a shaman who was with the expedition. She is dying of starvation. A death unfit for the Horde! Slay some of the nearby wildlife for their meat and cook it over the fire. Won'sa can tell us what happened to the missing expedition after she eats.",starts={{npcID=166906,x=0.582,y=0.746,mapID=1409}},ends={{npcID=166854,x=0.582,y=0.746,mapID=1409}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59933] = {id=59933,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Won'sa said the quilboar have kidnapped the missing expedition. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!",starts={{npcID=166906,x=0.582,y=0.746,mapID=1409}},ends={{npcID=166906,x=0.582,y=0.746,mapID=1409}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59934] = {id=59934,name="Enhanced Combat Tactics",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Won'sa said the quilboar have kidnapped the missing expedition... including my daughter. The quilboar will kill you if you're not prepared. They're much smarter and deadlier than murlocs. I won't see you die by their hands. We're going to spar one last time. When we are done, you will cleave a path straight through the quilboar!",starts={{npcID=166906,x=0.582,y=0.746,mapID=1409}},ends={{npcID=166906,x=0.582,y=0.746,mapID=1409}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59935] = {id=59935,name="Northbound",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Da quilboar kidnapped da rest of da expedition and took dem north. Dey said dey gonna use da expedition for some sorta sacrifice! Ya gotta head north as fast as ya can ta stop dem!",starts={{npcID=175030,x=0.582,y=0.746,mapID=1409}},ends={{npcID=166996,x=0.626,y=0.698,mapID=1409}},coords={x=0.582,y=0.746,source="quest_giver",mapID=1409},questType="standard"},
[59937] = {id=59937,name="Taming the Wilds",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="A hunter like yourself needs a good pet by your side. Did you not bring one with you? Hmm. I suppose I shall have to compensate for your lack of training. Listen closely and learn quickly. I will teach you how to tame a beast and make it your pet. You will need one if you are to fight the quilboar.",starts={{npcID=166996,x=0.626,y=0.698,mapID=1409}},ends={{npcID=166996,x=0.626,y=0.698,mapID=1409}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59938] = {id=59938,name="Down with the Quilboar",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I have discovered that the quilboar are performing a shadow ritual on a survivor from the missing expedition. The ritual is being performed by the tribe's leader, Geolord Grek'og . Slay Grek'og and save the survivor. Show this brute that the Horde is not to be trifled with.",starts={{npcID=166996,x=0.626,y=0.698,mapID=1409}},ends={{npcID=167019,x=0.562,y=0.59,mapID=1409}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59939] = {id=59939,name="Forbidden Quilboar Shadow Magic",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Quilboar are savage and violent. I did not think they knew how to use shadow magic. Obviously, we cannot allow them to continue their rituals. And certainly not on members of the Horde. Slay the quilboar in the den. They must learn the fatal error of their ways.",starts={{npcID=166996,x=0.626,y=0.698,mapID=1409}},ends={{npcID=167020,x=0.562,y=0.59,mapID=1409}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[59940] = {id=59940,name="The Choppy Booster Mk. 5",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You're in luck, 'cause I'm the ONE goblin who can help you find the rest of the expedition! Feast your eyes on this fancy device here. Stole it off a gnome, improved on it, and made it my own! I call it the Choppy Booster Mk. 5 . Use it to find Shuja and the others.",starts={{npcID=167019,x=0.562,y=0.59,mapID=1409}},ends={{npcID=167019,x=0.562,y=0.59,mapID=1409}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59941] = {id=59941,name="Re-sizing the Situation",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I call this gadget \"the Re-Sizer.\" It's what I used to unshrink the Choppy Booster Mk. 5. Look, I'm gonna be honest. I got, at best, a passing understandin' of how this thing works. That means I'm gonna be pushing a lot of buttons to see what happens. I'm sure we'll figure out how to upsize one of these boars. Then we'll use it to trample those undead goons! You hold the Re-Sizer while I fiddle with it. Then just press the button and, uh... hope for the best?",starts={{npcID=167019,x=0.562,y=0.59,mapID=1409}},ends={{npcID=167021,x=0.562,y=0.59,mapID=1409}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59942] = {id=59942,name="The Re-Deather",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I got the perfect plan. You're gonna ride the Choppy Booster Mk. 5 and BLAST those walkin' cadavers from the sky! I hereby dub the Re-Sizer the \"Re-Deather.\" We're gonna show them where the undead belong! Er, except for OUR undead. They're totally fine. Anyway, hop on the Choppy Booster Mk. 5 and I'll pilot it. Once we save Wrathion , we'll blast our way to all the other survivors!",starts={{npcID=167019,x=0.562,y=0.59,mapID=1409}},ends={{npcID=167128,x=0.524,y=0.532,mapID=1409}},coords={x=0.562,y=0.59,source="quest_giver",mapID=1409},questType="standard"},
[59943] = {id=59943,name="The Harpy Problem",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The ogres are planning to sacrifice the rest of the expedition to fuel this ritual to control Kalecgos, leader of the blue dragonflight. It seems one of the survivors was taken to the hills north of here. Bo scouted ahead to investigate. Come, we'll see what he has found.",starts={{npcID=167219,x=0.538,y=0.522,mapID=1409}},ends={{npcID=167291,x=0.568,y=0.462,mapID=1409}},coords={x=0.538,y=0.522,source="quest_giver",mapID=1409},questType="standard"},
[59944] = {id=59944,name="The Rescue of Herbert Gloomburst",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies plan to sacrifice the expedition's mage, a Forsaken by the name of Herbert Gloomburst . Herbert's ethics are... questionable, but he always strives to serve the Horde. We'll need his magic to stop the ogres. Let's move.",starts={{npcID=167290,x=0.568,y=0.462,mapID=1409}},ends={{npcID=167182,x=0.568,y=0.462,mapID=1409}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59945] = {id=59945,name="Harpy Culling",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies seem to be in league with the ogres. Many of them are gathering to attack our camp. We must thin their numbers and thwart their attempts to eliminate us. Perhaps they will learn it is best to leave the Horde be.",starts={{npcID=167291,x=0.568,y=0.462,mapID=1409}},ends={{npcID=167291,x=0.568,y=0.462,mapID=1409}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59946] = {id=59946,name="Purge the Totems",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The harpies have placed vile totems throughout the area to attain more power. We must destroy those totems in order to debilitate our foes. Take this torch and burn any totems you see. It is wise to weaken one's enemy before the fight even begins.",starts={{npcID=167291,x=0.568,y=0.462,mapID=1409}},ends={{npcID=167291,x=0.568,y=0.462,mapID=1409}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59947] = {id=59947,name="Message to Base",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Let us return to camp with Herbert in tow. We're one step closer towards thwarting the ogres and their plans.",starts={{npcID=167290,x=0.568,y=0.462,mapID=1409}},ends={{npcID=167212,x=0.522,y=0.552,mapID=1409}},coords={x=0.568,y=0.462,source="quest_giver",mapID=1409},questType="standard"},
[59948] = {id=59948,name="Westward Bound",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Thrall wants us to search west of here for the site of the next ritual. We could use your help. I've already died once. It's not an experience I'd care to repeat.",starts={{npcID=167221,x=0.528,y=0.564,mapID=1409}},ends={{npcID=167225,x=0.528,y=0.564,mapID=1409}},coords={x=0.528,y=0.564,source="quest_giver",mapID=1409},questType="standard"},
[59949] = {id=59949,name="Who Lurks in the Pit",level=6,requiredLevel=6,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="There's a whole lot of shadow energy coming from this pit. I'm guessing a ritual is being performed down there. And that means a sacrifice. Do you hear that? I've got the best hearing around, ever since I got this new ear sewn onto me. It sounds like there are some more of our soldiers trapped down there. Probably all webbed up. Won'sa and I will... stay up here and help anyone who gets out. You should jump in and rescue anyone who is left down there!",starts={{npcID=167225,x=0.528,y=0.564,mapID=1409}},ends={{npcID=167212,x=0.522,y=0.552,mapID=1409}},coords={x=0.528,y=0.564,source="quest_giver",mapID=1409},questType="standard"},
[59950] = {id=59950,name="Stocking Up on Supplies",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Provisioner Jin'hake managed to recover some other supplies from the shipwreck. Take a look at what he has before heading out.",starts={{npcID=167212,x=0.522,y=0.552,mapID=1409}},ends={{npcID=167212,x=0.522,y=0.552,mapID=1409}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59951] = {id=59951,name="A Druid's Form",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Thank you for rescuing me, . Allow me to aid you in your druidic studies. To escape from the pit, I took on the form of a stag. I may know of a way you can learn to do the same. Come with me. There is an ancient druid stone nearby. Let us use it to commune with the wilds.",starts={{npcID=166575,x=0.454,y=0.492,mapID=1409}},ends={{npcID=167473,x=0.454,y=0.492,mapID=1409}},coords={x=0.454,y=0.492,source="quest_giver",mapID=1409},questType="standard"},
[59952] = {id=59952,name="A Hunter's Trap",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="If you want to be called a true hunter, you'll need to learn the art of trapping. Fortunately, I happen to be an expert in it. First, you will need to gather supplies from the surrounding area so you can fashion a proper freezing trap . Herbert can supply you with a mote of ice. Scavenge the area for other materials. You will need the trap to handle another issue that has recently arisen.",starts={{npcID=167215,x=0.524,y=0.554,mapID=1409}},ends={{npcID=167215,x=0.524,y=0.554,mapID=1409}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59953] = {id=59953,name="Hunting the Stalker",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Now that you have your trap, we can move onto the true problem at hand. A strange creature not native to this island has been stalking our camp. I think we should capture it and see how it can help us. Set the freezing trap within these ruins to lure it out. We'll see just what we are dealing with.",starts={{npcID=167215,x=0.524,y=0.554,mapID=1409}},ends={{npcID=167215,x=0.524,y=0.554,mapID=1409}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59954] = {id=59954,name="A Mage's Knowledge",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You've got some good spells for a novice mage. There are a few things holding you back, though. For instance, it's absolutely clear to me you don't know Polymorph . If you did, you would've been using it on the harpies that were attacking us! Let's fix that. My spellbook has details on how to cast it... but my captors threw it into the nearby lake. Grab it for me, would you? Oh, and don't look through the book beforehand. You will almost certainly regret it if you do.",starts={{npcID=167309,x=0.522,y=0.554,mapID=1409}},ends={{npcID=167309,x=0.522,y=0.554,mapID=1409}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59955] = {id=59955,name="The Best Way to Use Sheep",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="I can't send you off without making sure you can cast Polymorph correctly. Why, if you messed it up you may transform someone into something completely different! I want to make sure I'm around to take notes if that happens. Let's see... ah, Throg will do nicely! I can spot a prime test subject from a mile away. Shall we begin?",starts={{npcID=167309,x=0.522,y=0.554,mapID=1409}},ends={{npcID=167309,x=0.522,y=0.554,mapID=1409}},coords={x=0.522,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59956] = {id=59956,name="A Monk's Focus",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You fought well against the harpies, but you'll need even more skill to best the challenges ahead. We must meditate and focus if we are to gain more strength. Come. I know of a place we can go.",starts={{npcID=167308,x=0.52,y=0.552,mapID=1409}},ends={{npcID=167537,x=0.52,y=0.552,mapID=1409}},coords={x=0.52,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59957] = {id=59957,name="One Last Spar",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Let's have a quick sparring session before returning to camp. I can sense new power rising from within you. I want to see it in action!",starts={{npcID=167537,x=0.52,y=0.552,mapID=1409}},ends={{npcID=167212,x=0.522,y=0.552,mapID=1409}},coords={x=0.52,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59958] = {id=59958,name="A Paladin's Service",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="While you were destroying that army of the undead, the ghost of a paladin approached me... and asked for you! They floated over to the ruins nearby. You should see what this ghost wants. I do not know much about the Light... but I know not to ignore a ghost.",starts={{npcID=167216,x=0.52,y=0.554,mapID=1409}},ends={{npcID=167179,x=0.576,y=0.52,mapID=1409}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59960] = {id=59960,name="A Cooling Trail",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13587,mapID=1543,ends={{npcID=355798,x=0.384,y=0.485,mapID=1543},{npcID=355798,x=0.384,y=0.485,mapID=1543}},questType="standard"},
[59961] = {id=59961,name="A Priest's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You're a trained priest, right ? I have a grim request for you. I passed by some injured members of the first expedition. I did what I could... but they were too far gone. Can you perform a ritual to lay them to rest? Their spirits deserve to rest with honor.",starts={{npcID=167216,x=0.52,y=0.554,mapID=1409}},ends={{npcID=167188,x=0.562,y=0.536,mapID=1409}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59965] = {id=59965,name="Resurrecting the Recruits",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Ya gotta cast Resurrection on dese recruits ta be savin' dem. Da necrotic magic of dis place be tuggin' at deir souls. Quickly, now!",starts={{npcID=167188,x=0.562,y=0.536,mapID=1409}},ends={{npcID=167188,x=0.562,y=0.536,mapID=1409}},coords={x=0.562,y=0.536,source="quest_giver",mapID=1409},questType="standard"},
[59967] = {id=59967,name="A Rogue's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Shuja mentioned a rogue from the first expedition. Goes by Drizza Sidestabber . Drizza was last seen heading northwest... towards a large bear's den. None of us can sneak around like you. See if you can find Drizza and bring her back here.",starts={{npcID=167216,x=0.52,y=0.554,mapID=1409}},ends={{npcID=167586,x=0.456,y=0.56,mapID=1409}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59968] = {id=59968,name="The Deadliest of Poisons",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You've got the poison. Now you gotta to take out that ogre. Goon's name is Gutgruk the Tough. He usually patrols around the citadel. I betcha it's lookin' for your expedition right now! Poison your blades, then take that monster down. Show him he ain't so tough!",starts={{npcID=167586,x=0.456,y=0.56,mapID=1409}},ends={{npcID=167216,x=0.52,y=0.554,mapID=1409}},coords={x=0.456,y=0.56,source="quest_giver",mapID=1409},questType="standard"},
[59969] = {id=59969,name="A Shaman's Duty",level=1,requiredLevel=1,faction="none",expansion=8,zoneID=10424,mapID=1409,description="Greetings, young one. Your compatriots cannot see me. Only you, for you have been trained in the ways of a shaman. The necrotic energies of this island have ensnared my pack. I need your aid to free them. Gather veil blossoms from surrounding area. Burn them on the campfire and breath deep of their smoke. Then you will be able to see my packmates and release them from their bonds.",questType="standard"},
[59970] = {id=59970,name="A Warlock's Bargain",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="While scouting the area, I saw an open portal near the bridge up the hill. That does not bode well for any of us. It seemed like another warlock tried to seal the portal, but failed. I know you dabble in such... affairs. Perhaps you could put your knowledge to good use and close that portal.",starts={{npcID=167216,x=0.52,y=0.554,mapID=1409}},ends={{npcID=167481,x=0.526,y=0.456,mapID=1409}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59971] = {id=59971,name="A Warrior's End",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Hail, ! You've grown stronger since we sparred on the boat. You may one day become a warrior of great renown! Speaking of which... I encountered a ghost on the bridge to the north that demands to meet a true warrior. Perhaps you can see what it wants. It did not seem hostile. It might even be willing to help us.",starts={{npcID=167216,x=0.52,y=0.554,mapID=1409}},ends={{npcID=162943,x=0.516,y=0.478,mapID=1409}},coords={x=0.52,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[59972] = {id=59972,name="Hjalmar's Final Execution",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="You now wield my most powerful skill, young warrior. Now use it to finish me! These ogres trapped my spirit here long ago for daring to defy them. Only through a glorious death will I finally be allowed to rest. It is the only way I will see my brothers and sisters in the afterlife.",starts={{npcID=162943,x=0.516,y=0.478,mapID=1409}},ends={{npcID=167216,x=0.52,y=0.554,mapID=1409}},coords={x=0.516,y=0.478,source="quest_giver",mapID=1409},questType="standard"},
[59975] = {id=59975,name="To Darkmaul Citadel",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="The last remaining survivor is being held within the ogre's citadel. Crenna and Herbert have a plan to get us inside. A small group of us will gather up north. You're coming with us. If we fail here, the ogres will gain control of Kalecgos and his powerful blue dragon magic.",starts={{npcID=167212,x=0.522,y=0.552,mapID=1409}},ends={{npcID=167596,x=0.522,y=0.552,mapID=1409}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59978] = {id=59978,name="Right Beneath Their Eyes",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="We need to get into Darkmaul Citadel, rescue the last survivor, and stop Gor'groth. Herbert and Crenna are going to cast a spell to make you look an ogre... and then you're going to take us in as your \"prisoners.\" Speak with Herbert when you're ready.",starts={{npcID=167596,x=0.522,y=0.552,mapID=1409}},ends={{npcID=167633,x=0.402,y=0.324,mapID=1409}},coords={x=0.522,y=0.552,source="quest_giver",mapID=1409},questType="standard"},
[59979] = {id=59979,name="Like Ogres to the Slaughter",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This is worse than I thought. The ogres were counting on us to stage a rescue attempt. It seems that they plan to attack our camp while they near completion of the ritual. We can't let that happen. Crush the ogres! Show them the strength of the Horde!",starts={{npcID=167632,x=0.402,y=0.324,mapID=1409}},ends={{npcID=167632,x=0.402,y=0.324,mapID=1409}},coords={x=0.402,y=0.324,source="quest_giver",mapID=1409},questType="standard"},
[59980] = {id=59980,name="Catapult Destruction",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="As we snuck in here I noticed the ogres erecting catapults to destroy our camp. Cork must have anticipated this and gave me several explosives to use, \"just in case\". Take these explosives and blow up those catapults ! Also don't shake them too hard.",starts={{npcID=167630,x=0.402,y=0.326,mapID=1409},{npcID=167631,x=0.404,y=0.324,mapID=1409}},ends={{npcID=167630,x=0.402,y=0.326,mapID=1409},{npcID=167631,x=0.404,y=0.324,mapID=1409}},coords={x=0.402,y=0.326,source="quest_giver",mapID=1409},questType="standard"},
[59981] = {id=59981,name="Controlling their Stones",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Warlord Thunderwalker won't last much longer. Soon, his life essence will be completely drained. Gor'groth mentioned that they are keeping him captive through the use of ward stones . I want you to recover these ward stones and bring them here so we can release Thunderwalker.",starts={{npcID=167633,x=0.402,y=0.324,mapID=1409}},ends={{npcID=167183,x=0.4,y=0.322,mapID=1409}},coords={x=0.402,y=0.324,source="quest_giver",mapID=1409},questType="standard"},
[59984] = {id=59984,name="Dungeon: Darkmaul Citadel",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Gor'groth seeks to use shadow magic to gain control of Kalecgos, the aspect of the Blue Dragonflight. He's collected enough life essence to attempt to finish the ritual. I do not know what will happen, but we cannot let him complete it! Gor'groth will not stop until he is slain! You must storm the citadel and slay Gor'groth before he can complete his ritual! I would charge in beside you, were I not still recovering from his dark magic.",starts={{npcID=167183,x=0.4,y=0.322,mapID=1409}},ends={{npcID=167675,x=0.396,y=0.32,mapID=1409}},coords={x=0.4,y=0.322,source="quest_giver",mapID=1409},questType="standard"},
[59985] = {id=59985,name="An End to Beginnings",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=13644,mapID=2022,description="You've done well here, . Kalecgos and Wrathion are planning to continue on to the Dragon Isles. I must return to Orgrimmar. This shadow magic is concerning... and requires that I look into it more. Talk with Kalecgos . He'll get you to the Dragon Isles and inform you about what's going on there.",starts={{npcID=167675,x=0.396,y=0.32,mapID=1409}},ends={{npcID=168431,x=0.524,y=0.882,mapID=85},{npcID=244496,x=0.812,y=0.28,mapID=2022}},coords={x=0.396,y=0.32,source="quest_giver",mapID=2022},questType="standard"},
[59986] = {id=59986,name="Wide Worlds of Catalysts",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13367,mapID=1662,description="Catalysts come in different forms, for now we shall introduce you to two of them. Speed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover. Quality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. Return to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.",questType="standard"},
[59999] = {id=59999,name="Rebirth of the Grove",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13367,mapID=1662,description="Though not yet withered, the conservatory wilts amidst the drought. This grove is not what it once was. As warden, I bear the twin burdens of guilt and shame. Fate saw to this grove's decay and my failure to prevent it. But fate has also seen to hope in its renewal. Hope in you. I beseech you, mortal, to seek out Zayhad in the Heart of the Forest and restore what has been lost. For as the wounded spirits must be reborn, so too must this grove.",starts={{npcID=166476,x=0.334,y=0.61,mapID=1662}},ends={{npcID=166476,x=0.334,y=0.61,mapID=1662}},coords={x=0.334,y=0.61,source="quest_giver",mapID=1662},questType="standard"},
