[60162] = {id=60162,name="The Art of Taming",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="Quite the surprise to find this beast so hale and hearty. It seems to have taken a liking to you. If you're ever going to be as great as one of the Dawntrackers, you must learn how to handle multiple pets. Allow me to show you how.",starts={{npcID=167215,x=0.524,y=0.554,mapID=1409}},ends={{npcID=167215,x=0.524,y=0.554,mapID=1409}},coords={x=0.524,y=0.554,source="quest_giver",mapID=1409},questType="standard"},
[60172] = {id=60172,name="This Quest is Temporary",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Dropping out of the sky is a key part of this playtest, so enjoy the ride.",questType="standard"},
[60174] = {id=60174,name="The Divine's Shield",level=1,requiredLevel=1,faction="horde",expansion=8,zoneID=10424,mapID=1409,description="This island has foul necromancy here in addition to the shadow magic. The Light can only just reach this place. Call upon its Divine Shield to step through the barrier before us unharmed and destroy this vile altar. Show the darkness on this island that you are protected by the Light's embrace.",starts={{npcID=167179,x=0.576,y=0.52,mapID=1409}},ends={{npcID=167179,x=0.576,y=0.52,mapID=1409}},coords={x=0.576,y=0.52,source="quest_giver",mapID=1409},questType="standard"},
