[60267] = {id=60267,name="Prison of the Forgotten",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari may know more of its purpose.>",questType="standard"},
[60288] = {id=60288,name="Supplies from the Necrolords",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,questType="standard"},
[60343] = {id=60343,name="Welcome to Orgrimmar",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="The warchief will be waiting for our mission report from Exile's Reach. I must deliver it at once. For now, Cork Fizzlepop will show you around the city. Orgrimmar has much to offer, so explore it as you see fit. I'll send for you once I've given my report to the warchief.",starts={{npcID=168431,x=0.524,y=0.882,mapID=85}},ends={{npcID=168441,x=0.52,y=0.854,mapID=85}},coords={x=0.524,y=0.882,source="quest_giver",mapID=85},questType="standard"},
[60344] = {id=60344,name="Finding Your Way",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Orgrimmar 's a big city. Way too big to explore on foot. Warlord Grimaxe has arranged for you to receive a mount to help you get around. She said to speak with Rohaka at the stables... but I can't seem to remember the way there. Don't worry, ! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master. Then we can be on our way!",starts={{npcID=168441,x=0.52,y=0.854,mapID=85}},ends={{npcID=168540,x=0.714,y=0.474,mapID=85}},coords={x=0.52,y=0.854,source="quest_giver",mapID=85},questType="standard"},
[60346] = {id=60346,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Telotha Pinegrove to learn more about specializations!",ends={{npcID=168553,x=0.73,y=0.434,mapID=85}},questType="standard"},
[60347] = {id=60347,name="What's Your Specialty?",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="Hey, ! Have you decided on a combat specialization yet? Since you're a , you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Tamanji to learn more about specializations!",ends={{npcID=168551,x=0.738,y=0.438,mapID=85}},questType="standard"},
