[60359] = {id=60359,name="Home Is Where the Hearth Is",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=1637,mapID=85,description="I don't know about you, but I'm in the mood for some good ol' fashioned recreation! Why don't we head over to The Wyvern's Tail and cool off with a few pints of Cobo Cola? While we're there, speak with Innkeeper Nufa to make The Wyvern's Tail your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a wyvern, but you'll save yourself some dough in the process!",ends={{npcID=46642,x=0.704,y=0.49,mapID=85}},questType="standard"},
[60361] = {id=60361,name="Battle for Azeroth: Mission Statement",level=7,requiredLevel=7,faction="horde",expansion=8,zoneID=8499,mapID=862,description="The warchief has requested to meet with you in person. Lady Sylvanas was impressed with the prowess and courage you displayed during our mission to Exile's Reach. Now that you've arrived, I will make the introduction.",starts={{npcID=168431,x=0.524,y=0.882,mapID=85}},ends={{npcID=121210,x=0.58,y=0.628,mapID=862}},coords={x=0.524,y=0.882,source="quest_giver",mapID=862},questType="standard"},
[60362] = {id=60362,name="Blank",level=10,requiredLevel=10,faction="horde",expansion=8,zoneID=1519,mapID=84,description="Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.",questType="standard"},
[60474] = {id=60474,name="Spawn Tracking Unit-Specified World Effect in a WMO Bug",level=1,requiredLevel=1,faction="none",expansion=8,zoneID=4019,questType="standard"},
[60566] = {id=60566,name="Into the Light",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I am afraid that you must endure the next stretch of the stroll without me, $p. While my compatriots and I have secured access to the elevator that shall carry us up to Sinfall, we are unable to utilize it. The Master has redirected a massive beam of Light directly onto the elevator's landing. Venthyr that get close are obliterated. Dredgers sent up never return. We need someone who can walk in the Light to discover what is happening up there. Lady Sybille will show you the way.",starts={{npcID=158694,x=0.32,y=0.476,mapID=1525}},ends={{npcID=169105,x=0.304,y=0.456,mapID=1525}},coords={x=0.32,y=0.476,source="quest_giver",mapID=1525},questType="standard"},
