[61391] = {id=61391,name="The Eye of the Jailer",level=55,requiredLevel=55,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Yes... I remember you... Do you think that because you evaded my grasp once, that I would let it happen again? No. The Maw answers to me. All that befalls you here will be because I willed it so. Death comes for you, mortal. Everywhere you go, my eye is upon you.",questType="standard"},
