[61554] = {id=61554,name="The Play's The Thing",level=60,requiredLevel=60,faction="none",expansion=8,description="You may be wondering about the last boon we may grant thee, O' champion of Ardenweald, petitioner to our Hunt. Before our Queen grants you our power and we accept you formally into our midst, there are certain... Traditions which we must uphold. Lady Moonberry awaits you in the Sanctum Hall with more information. Break a leg.",questType="standard"},
[61556] = {id=61556,name="Party Crashers",level=60,requiredLevel=60,faction="none",expansion=8,questType="standard"},
[61557] = {id=61557,name="An Echo in the Darkness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="$p, I... I am beset by dark visions. A power emanating from within Torghast. A familiar sensation. One I have not felt since... Come to Oribos . Do not delay.",questType="standard"},
