[61729] = {id=61729,name="Adventurer: Rahel",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,starts={{npcID=164741,x=0.578,y=0.588,mapID=1525}},ends={{npcID=164741,x=0.578,y=0.588,mapID=1525}},coords={x=0.578,y=0.588,source="quest_giver",mapID=1525},questType="standard"},
[61736] = {id=61736,name="Stolen Away",level=50,requiredLevel=50,faction="none",expansion=8,description="There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Whitemane. She can tell you the rest.",questType="standard"},
[61737] = {id=61737,name="Stolen Away",level=50,requiredLevel=50,faction="none",expansion=8,description="There is much you need to be told, . The Scourge has returned. With the Helm of Domination shattered, their evil runs rampant. Unchecked. What's worse, Sylvanas Windrunner has sent her agents into the very heart of our kingdoms to take those who thwarted her efforts in the war. Speak to Nazgrim. He can tell you the rest.",questType="standard"},
[61760] = {id=61760,name="The Traitor Unmasked",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="We must waste no time in warning the margrave of Kel'Thuzad 's treachery. His reckless toying with forbidden powers could bring ruin to the house and beyond! Let us put an end to this!",starts={{npcID=173172,x=0.662,y=0.322,mapID=1536}},coords={x=0.662,y=0.322,source="quest_giver",mapID=1536},questType="standard"},
[61765] = {id=61765,name="Words of Warding",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The towering citadel in the distance is protected by perilous walls, but its greatest dangers cannot be seen with mortal eyes. The Mawsworn have placed invisible runes of warding throughout Perdition Hold. These traps have caught many intruders unaware. The runes can be dispelled, but only if you can see them. I believe one of their soulcloaks should give you the sight you require. Good luck.",starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group"},
