[62213] = {id=62213,name="A Brokered Deal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="Hey, . I've found a lucrative business proposition that'll help me... us... greatly! See, Au'narim is willing to give us supplies if we can help him recover from a trade deal that went sideways. Apparently, several of his cohorts never returned from a job. He needs us to follow their path and recover the item they failed to deliver. Simple, right? To ensure we don't have any mishaps, I've taken the liberty of acquiring a few items that may be of help to us. So, you in?",starts={{npcID=159238,x=0.552,y=0.682,mapID=1536}},ends={{npcID=159830,x=0.536,y=0.474,mapID=1536}},coords={x=0.552,y=0.682,source="quest_giver",mapID=2151},questType="standard"},
[62226] = {id=62226,name="Talethi's Desire",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
