[62231] = {id=62231,name="Velkein's Blade",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62234] = {id=62234,name="Power of the Colossus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have another task for you, Maw Walker. Deep within Perdition Hold, there lurks a menacing mechanization known as the Soulsteel Colossus. It must be destroyed before it wreaks havoc upon us. Travel to the Hold, and then across the bridge into the Altar of Domination. There, casting its vast shadow upon The Maw , you will find the Soulsteel Colossus. Shatter the colossus and bring me its power source as proof of your victory.",starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group"},
[62236] = {id=62236,name="Rattlebag's Lost Armor",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62256] = {id=62256,name="Asset Extraction",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=14433,mapID=2151,description="Hey, it's my good pal ! Listen, I'm in a bit of a bind here. I've been trying to negotiate a deal with the broker Au'larrynar and he needs a little something, a job done before he'll accept. The deal is he had an associate who went missing with a rare item. He's asked that I... we... locate and return the missing property. The associate was last seen in Ardenweald. I know, strange place, way too bright for me. But, I... we... really need this deal to go through! So, you ready to go?",starts={{npcID=158259,x=0.504,y=0.474,mapID=1536},{npcID=159238,x=0.552,y=0.682,mapID=1536}},ends={{npcID=166640,x=0.536,y=0.478,mapID=1536}},coords={x=0.504,y=0.474,source="quest_giver",mapID=2151},questType="standard"},
