[62394] = {id=62394,name="House In Decline",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Our forces are gathering. Soon it will be time to move against the House of Rituals. See what you can do to continue strengthening our position.",questType="standard"},
[62417] = {id=62417,name="Go Beyond!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?",questType="standard"},
[62420] = {id=62420,name="Snapper Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Snapper Soul is determined. The shape of the dragon turtle will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[62421] = {id=62421,name="Gulper Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Gulper Soul is patient and calm. The shape of the Gulper will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[62422] = {id=62422,name="Ardenmoth Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald . Delicate looking creatures, they have hidden strength. Their magic can soothe the most tortured soul... or send the unwary into an eternal sleep. The shape of the moth will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
