[62425] = {id=62425,name="Veilwing Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Ardenweald is more respected for its fierce defense of its family or territory than the veilwing. You have defeated a foe who endangered not only Ardenweald , but all of the Shadowlands. For this, Champion of Ardenweald , you have earned a special boon - the ability to call upon the essence of the veilwing and take their shape.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[62426] = {id=62426,name="Gryphon Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Gryphon Soul is agile and swift. The shape of the gryphon will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
