[62461] = {id=62461,name="Stalking the Warrens",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="So, they are creating magical beasts deep within the Warrens. Their power is... substantial. Maw Walker, I must trust in you to handle this. While I can provide insight, in combat I must admit your prowess exceeds my own. Hunt the beasts that they train to hunt us. Show the Mawsworn that we too can bare fangs.",starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="group"},
[62483] = {id=62483,name="Steward Mail Pouch",level=60,requiredLevel=60,faction="both",expansion=8,description="steward 's size. You are certain your steward will love it.>",questType="standard"},
