[62801] = {id=62801,name="The Call of Fate",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us. Fate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice. Return to Oribos , , that I might help guide your path. The Purpose is our way.",questType="standard"},
[62855] = {id=62855,name="Edict of the Eternal Ones",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia. Return to the place of your passing, and you shall find what you left behind.",questType="standard"},
[62886] = {id=62886,name="A Call to Service",level=60,requiredLevel=60,faction="none",expansion=8,description="The Heart of the Forest requires anima to be renewed and to grow. The Wild Hunt will need your help to recover what we need. Together we strand strong. Speak with Blodwyn. She has been guiding assistance to where it is most needed.",questType="standard"},
[62917] = {id=62917,name="Shared Souls",level=60,requiredLevel=60,faction="none",expansion=8,description="The power of the Harvesters flows through your mortal body. But you may wield even greater might by binding your soul to another. Doing so has no known drawbacks, but offers many advantages for both parties involved. The Accuser will oversee the process. Meet her at the Forge of Bonds when you are ready.",questType="standard"},
[62976] = {id=62976,name="Artisan Tool Belt",level=60,requiredLevel=60,faction="both",expansion=8,description="steward to not only assist you with crafting, but also carry common trade goods.>",questType="standard"},
[62993] = {id=62993,name="The Riddle of Death",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[62999] = {id=62999,name="Champion: Croman",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
