[63063] = {id=63063,name="Sanctum Upgrade: Mirror Network",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1525,description="We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Once you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.",starts={{npcID=172605,x=0.558,y=0.272,mapID=1525}},ends={{npcID=167160,x=0.47,y=0.572,mapID=1525}},coords={x=0.558,y=0.272,source="quest_giver",mapID=1525},questType="standard"},
[63101] = {id=63101,name="XX REUSEME",level=60,requiredLevel=60,faction="none",expansion=8,description="As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. Seek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.",questType="standard"},
[63213] = {id=63213,name="Naladu the Elder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1525,starts={{npcID=176253,x=0.616,y=0.602,mapID=1525},{npcID=176253,x=0.616,y=0.602,mapID=1525}},ends={{npcID=176253,x=0.616,y=0.602,mapID=1525},{npcID=176253,x=0.616,y=0.602,mapID=1525}},coords={x=0.616,y=0.602,source="quest_giver",mapID=1525},questType="standard"},
[63418] = {id=63418,name="Exploited Explorers",level=10,requiredLevel=10,faction="none",expansion=8,description="Chuck explains that something weird is happening in the jungle, and that his group has been captured by wild fungarians. He asks you to rescue his friends to help find out what's going on with the jungle.",questType="standard"},
[63419] = {id=63419,name="Spores Galore",level=10,requiredLevel=10,faction="none",expansion=8,description="Chuck goes over again how the jungle seems to be alive and all wrong. He asks you to recover the spores that are on the fungarians and the beasts they've infected. Chuck is worried whatever is happening isn't natural.",questType="standard"},
[63494] = {id=63494,name="The Anvil-Thane's Designs",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,mapID=84,description="I see you eyein' our weapons here. Wouldnae ye know, I forged them myself! So far, I've got designs for a staff, a one-handed axe, and a shield... I could make ye some, if you'd like! O' course, that's what I'd normally say. Unfortunately I lost the designs in a bet down at the Grim Guzzler. If ye could get them back, as well as gather the materials, I'd be happy to forge ye some weapons!",starts={{npcID=144154,x=0.57,y=0.318,mapID=84}},ends={{npcID=176828,x=0.516,y=0.33,mapID=84}},coords={x=0.57,y=0.318,source="quest_giver",mapID=84},questType="standard"},
[63501] = {id=63501,name="It's Called Borrowing",level=50,requiredLevel=50,faction="alliance",expansion=8,zoneID=1584,mapID=84,description="Thurgaden's designs for his weaponry, but are hard to parse. Notes are scribbled in the margins in messy handwriting, listing modifications and notes Thurgaden left for himself. Two notes in particular stand out to you. One denotes that he lent his engraving tool to the core hound trainer Kasea Angerforge, and the other wonders how many elementals they employ at the Grim Guzzler brewing operation.>",ends={{npcID=144154,x=0.57,y=0.318,mapID=84}},questType="standard"},
[63576] = {id=63576,name="The First Move",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="While the covenants labor to defend the Shadowlands, the Jailer has not sat idle within Torghast. It seems he intends to set the next phase of his scheme into motion. Polemarch Adrestes has brought us disturbing news from Elysian Hold. He will recount what he witnessed once you arrive. Make haste. I fear that time grows short.",questType="standard"},
