[63671] = {id=63671,name="Favor: The Nathrezim Documents",level=10,requiredLevel=10,faction="none",expansion=8,zoneID=10413,mapID=1525,description="This item will be of great interest to the brokers. Per your previous deal with The Night Market, you should bring it to Ta'xera. You will be fairly compensated.",questType="standard"},
[63684] = {id=63684,name="Feral Shadehound",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="feral shadehound and bind it to you.>",questType="standard"},
[63714] = {id=63714,name="To the Vault",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Thanks to the Bonesmith's repairs of both conduits, anima should now be flowing to the vault. That gives us a chance to get inside--assuming we can reach it. Our Maldraxxi allies have wrangled transportation to get us to and from the vault. I suggest we make haste. If the Jailer's minions obtain the sigil of the Primus before we do, it won't just be Korthia that suffers. All the Shadowlands may be forfeit. Let's go, Maw Walker. Our forces will be awaiting us.",starts={{npcID=177451,x=0.35,y=0.352,mapID=1961}},ends={{npcID=177459,x=0.49,y=0.642,mapID=1961}},coords={x=0.35,y=0.352,source="quest_giver",mapID=1961},questType="standard"},
[63735] = {id=63735,name="Recover the Research",level=60,requiredLevel=60,faction="none",expansion=8,description="Though the circumstances are grim, we cannot neglect the Purpose. On the bodies of the attendants in the Seeker's Quorum, you will find scrolls detailing our ongoing research. What is written on each of these scrolls represents efforts equal to many of your lifetimes. Retrieve them, before they are destroyed and lost forever.",questType="standard"},
[63751] = {id=63751,name="A Terrible Power",level=60,requiredLevel=60,faction="none",expansion=8,description="This strange shard pulses in your hand. An aura of dread radiates forth from it like a chill wind, sending a shiver down your spine. Perhaps the Primus could tell you more about this... if you could find him.",questType="standard"},
[63757] = {id=63757,name="Looting the Looters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,questType="standard"},
[63771] = {id=63771,name="Fate's Reminder",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Fatescribe Roh-Tahl awaits you within Oribos , should you ever wish to change the course of fate. You may speak with him at your leisure.",questType="standard"},
[63953] = {id=63953,name="Korrak's Revenge",level=1,requiredLevel=1,faction="none",expansion=8,questType="standard"},
[63987] = {id=63987,name="Ve'lor's Lost Parcel",level=50,requiredLevel=50,faction="none",expansion=8,zoneID=13575,mapID=1912,questType="standard"},
[64131] = {id=64131,name="Tracking Quest",level=50,requiredLevel=50,faction="none",expansion=8,questType="standard"},
[64159] = {id=64159,name="Repatriate Rare Supplies",level=0,requiredLevel=0,faction="none",expansion=8,description="The rebels have stolen supplies from surrounding camps. You have proven yourself adept at correcting such situations. I trust you can aid us in resolving this situation.",questType="standard"},
[64162] = {id=64162,name="Ritual Rival",level=0,requiredLevel=0,faction="none",expansion=8,description="Yet another rival Kahn has risen out of the rebel tribes. I'd take care of then myself, but I'm busy overseeing things here. I trust you can teach them the error of their ways?",questType="standard"},
[64163] = {id=64163,name="Revenge Against Renegades",level=0,requiredLevel=0,faction="none",expansion=8,description="Rebel clans have laid claims to some of our camps across the river. Such rebellious rabble need dealing with. I trust that you are capable of teaching these rebels a lesson on my behalf? The camps are an untidy mess as well, so just ignore the chaos for now. We can resolve that later once order is restored.",questType="standard"},
