[64202] = {id=64202,name="Gotta Hand It To Ya",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Your power Maw Walker... it rivals even mine before Zovaal separated my body. This is but a small part of my whole, but more than enough... Allow me to aid you in your efforts against Zovaal. In doing so my vengeance will be fulfilled.",questType="standard"},
