[64551] = {id=64551,name="Legend of the Animaswell",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Korthia . Merick Feldscar in the Seat of the Primus would be able to help you put together a team to search for it.>",ends={{npcID=165321,x=0.39,y=0.48,mapID=1698}},questType="standard"},
