[64639] = {id=64639,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[64650] = {id=64650,name="Hyena Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Hyena Soul is fiery and spry. The shape of the hyena will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[64651] = {id=64651,name="Cobra Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Cobra Soul is covetous and protective. The shape of the cobra will be yours to call upon.>",ends={{npcID=174209,x=0.38,y=0.254,mapID=1565},{npcID=174209,x=0.38,y=0.254,mapID=1565}},questType="standard"},
[64710] = {id=64710,name="Whispering Felflame Crystal",level=1,requiredLevel=1,faction="both",expansion=8,zoneID=7502,mapID=627,description="The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran . Perhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.",questType="standard"},
[64741] = {id=64741,name="Security Check",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I do not understand--these are my brethren! How can they be so careless, so unconcerned with both greedy cartels and the Mawsworn at their doorstep? Their protective technology is antiquated. It will not keep danger out. If I cannot persuade them to leave, I can at least ensure they are safe where they insist on staying. I do not want to lose my friends again. There should be four hidden conduits around the edge of the shield. Take this kit. It will allow you to inspect and repair them, if needed.",starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64742] = {id=64742,name="Traces of Tampering",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="So the shield has been sabotaged. Of course the ruthless Cartel Xy are the first to attempt to profit off this land. Their greed has put us all in even more danger. We must stop them. Let us search together for signs of their passage.",starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64743] = {id=64743,name="Xy Are You Doing This?",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We cannot see them, but I am certain this is where Cartel Xy has established their base. Something must have drawn Xy to this area of Zereth Mortis specifically, and we must discover what it is if we are to protect our friends here. Their cloaks do not cover their supplies very well. See what information you can gather from their belongings.",starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64744] = {id=64744,name="Broker Decloaker",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Do you sense a shift in the air? They may be hidden, but Cartel Xy is near. Fortunately, the devices they use to cloak themselves are familiar to me. Here; take this. Place it on the ground and it will reveal nearby agents... for a time. Stop them, even if you must take their lives.",starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="standard"},
[64758] = {id=64758,name="Following the Leader",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We sealed the door to the Slumbering Vault when we first arrived. It is a sanctum, a cradle of all that is precious here. The power that sleeps within should not be touched by us. If the Xy leader made it past the shields while we were distracted by the beauty of this place, I shudder to think of what they have already disturbed. Hurry! We must go to the Slumbering Vault and ensure its safety.",starts={{npcID=180936,x=0.336,y=0.598,mapID=1970}},ends={{npcID=180936,x=0.336,y=0.598,mapID=1970}},coords={x=0.336,y=0.598,source="quest_giver",mapID=1970},questType="standard"},
[64760] = {id=64760,name="Technical Difficulties",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The console is going haywire! We have to fix it! Maybe these buttons do something?",starts={{npcID=180936,x=0.336,y=0.598,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.336,y=0.598,source="quest_giver",mapID=1970},questType="standard"},
[64803] = {id=64803,name="Testing One Two",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The creatures of Zereth Mortis have existed here since well before I created Domination. We have seen the effects that Zovaal's forces have had on them, but I believe there is more to be learned. Use the helm on the denizens of Zereth Mortis and see what you can uncover about a natural resistance.",starts={{npcID=181245,x=0.332,y=0.688,mapID=1970}},ends={{npcID=181266,x=0.562,y=0.832,mapID=1970},{npcID=184182,x=0.592,y=0.788,mapID=1970}},coords={x=0.332,y=0.688,source="quest_giver",mapID=1970},questType="standard"},
[64871] = {id=64871,name="The Dragon at the Door",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13769,mapID=85,description="That blue dragon will collapse the creche and trap us inside! He claims to serve Malygos. That name is familiar, but... why would any dragon want to keep us prisoner? Listen, $p. We were trained to fight beside the dragons, not against them. But we have been left with no choice. Time to do what must be done, evoker.",ends={{npcID=184269,x=0.442,y=0.614,mapID=85}},questType="standard"},
[64872] = {id=64872,name="The Fire Within",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=14433,mapID=2151,description="You are an evoker, . The best of the best. An elite soldier who has mastered the skills of each of our weyrns. I expect a lot of you. Your memories may be broken, but the might of dragons courses through your veins. Harness it. One of your most potent weapons is your breath attack. The fire within becomes more powerful the longer you inhale. These insects swarming over our training grounds should make fine targets.",starts={{npcID=184269,x=0.442,y=0.614,mapID=85}},ends={{npcID=184269,x=0.442,y=0.614,mapID=85}},coords={x=0.442,y=0.614,source="quest_giver",mapID=2151},questType="standard"},
[64873] = {id=64873,name="Stretch Your Wings",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=13769,mapID=85,description="I am heartened to see that so many escaped the War Creche. My own weyrn... was not as fortunate. There are other creches throughout the Reach, filled with dracthyr in peril. Strong wings will be needed to reach them. Focus. Remember your training. Get a feel for the wind again. You must regain your strength and fly to the other creches. The time for rest is over.",starts={{npcID=181054,x=0.444,y=0.61,mapID=85}},ends={{npcID=192889,x=0.448,y=0.578,mapID=85}},coords={x=0.444,y=0.61,source="quest_giver",mapID=85},questType="standard"},
[64941] = {id=64941,name="Chicken Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Chicken Soul is perky and voracious. The shape of the chicken will be yours to call upon.>",questType="standard"},
[64942] = {id=64942,name="Call of the Primus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10565,mapID=1670,description="Though we fought to stop the Jailer in the Sanctum of Domination, we failed. He enveloped Oribos in the Maw, struck down the Arbiter, and opened the way to Zereth Mortis . The time has come to follow him. Within the Arbiter's Chamber, we will forge our own path. Hurry, Maw Walker. The fate of the Shadowlands, and all the realms beyond, is at stake.",ends={{npcID=181655,x=0.332,y=0.504,zoneID=13863}},questType="standard"},
[64944] = {id=64944,name="A Hasty Voyage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The path to Zereth Mortis is open. We must part ways here. The Eternal Ones are forbidden from returning to the place of our creation. Zovaal has defied the most sacred laws of the Progenitors. You must undertake this journey alone. Go. Find a foothold in Zereth Mortis so that we can send the covenant forces through. Then we will pursue the Jailer and end his madness.",starts={{npcID=181655,x=0.332,y=0.504,zoneID=13863}},ends={{npcID=181931,x=0.34,y=0.608,mapID=1970}},coords={x=0.332,y=0.504,source="quest_giver",mapID=1970},questType="standard"},
[64958] = {id=64958,name="The Forces Gather",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I am relieved that you survived the passage to Zereth Mortis . From what I've overheard of Pelagos's conversation with Kleia, it sounds like you had an incredible journey. These Enlightened brokers could make valuable allies. Their knowledge of the automa and the land itself should help us against the Jailer. Our forces are gathered and ready to follow you to Zereth Mortis . The final battle lies before us, $p.",ends={{npcID=177486,x=0.348,y=0.648,mapID=1970}},questType="standard"},
[64959] = {id=64959,name="Otter Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1565,description="Otter Soul is swift and boastful. The shape of the otter will be yours to call upon.>",questType="standard"},
